// @vitest-environment node
import fs from "node:fs";
import { describe, expect, it } from "vitest";

/**
 * Guards the committed brand assets (see assets/brand/README.md). The assets
 * are generated by `npm run brand:assets` from the two source PNGs; this test
 * fails if a generated file is deleted, reverted to the old radar mark, or
 * drifts from the brand palette. It never runs the generator (no ImageMagick
 * needed here) — it only checks the committed outputs.
 */
function read(path: string): string {
  return fs.readFileSync(path, "utf8");
}

function pngSize(path: string): { width: number; height: number } {
  const buffer = fs.readFileSync(path);
  expect(buffer.subarray(1, 4).toString("ascii")).toBe("PNG");
  return { width: buffer.readUInt32BE(16), height: buffer.readUInt32BE(20) };
}

const GRADIENT_STOPS = ["#7239e2", "#4227bb", "#1f3fbd", "#178fcb", "#6fe7df"];

describe("Brand assets", () => {
  it("commits the brand sheet sources the generator reads", () => {
    for (const source of ["assets/brand/mark.png", "assets/brand/wordmark.png"]) {
      expect(fs.existsSync(source), source).toBe(true);
      expect(fs.statSync(source).size).toBeGreaterThan(1000);
    }
  });

  it("ships the gradient-mark app tile as both web icons", () => {
    const pub = read("public/icon.svg");
    const web = read("website/icon.svg");
    expect(pub).toBe(web);
    expect(pub).toContain('viewBox="0 0 512 512"');
    expect(pub).toContain('fill="#0F1222"');
    expect(pub).toContain('fill-rule="evenodd"');
    for (const stop of GRADIENT_STOPS) {
      expect(pub, `icon.svg missing gradient stop ${stop}`).toContain(stop);
    }
    // The old radar/bridge mark must not come back.
    expect(pub).not.toContain("stroke-dasharray");
    expect(pub).not.toContain("#34D399");
  });

  it("ships correctly sized favicon and apple-touch-icon PNGs", () => {
    expect(pngSize("website/favicon-32.png")).toEqual({ width: 32, height: 32 });
    expect(pngSize("website/apple-touch-icon.png")).toEqual({ width: 180, height: 180 });
  });

  it("packs the macOS icon as PNG icns entries at 128/256/512/1024", () => {
    const icns = fs.readFileSync("macos/AirBridge.icns");
    expect(icns.toString("ascii", 0, 4)).toBe("icns");
    expect(icns.readUInt32BE(4)).toBe(icns.length);
    const types: string[] = [];
    let offset = 8;
    while (offset < icns.length) {
      const type = icns.toString("ascii", offset, offset + 4);
      const length = icns.readUInt32BE(offset + 4);
      expect(length).toBeGreaterThan(8);
      // PNG signature: 89 50 4E 47 0D 0A 1A 0A.
      expect([...icns.subarray(offset + 8, offset + 16)]).toEqual([
        0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a,
      ]);
      types.push(type);
      offset += length;
    }
    expect(types).toEqual(["ic07", "ic08", "ic09", "ic10"]);
  });

  it("draws the Android launcher mark as a traced even-odd vector on brand navy", () => {
    const foreground = read("android/app/src/main/res/drawable/ic_launcher_foreground.xml");
    expect(foreground).toContain('android:viewportWidth="108"');
    expect(foreground).toContain('android:fillType="evenOdd"');
    expect(foreground).toContain('android:type="radial"');
    expect(foreground).toContain('<aapt:attr name="android:fillColor">');
    expect(foreground).toContain('xmlns:aapt="http://schemas.android.com/aapt"');
    expect(foreground).not.toContain("android:gradientType");
    expect(foreground).toContain("android:startColor");
    expect(foreground).toContain("android:endColor");
    expect(foreground).toContain("#7A3BF5");
    expect(foreground).toContain("#35D6D6");
    const pathData = foreground.match(/android:pathData="([^"]+)"/)?.[1] ?? "";
    expect(pathData.length).toBeGreaterThan(1000);
    expect(pathData.startsWith("M")).toBe(true);

    const colors = read("android/app/src/main/res/values/colors.xml");
    expect(colors).toContain("#0F1222");
    expect(colors).not.toContain("#FFFFFF");
  });

  it("renders the in-app logo from the generated mark module, not the old radar drawing", () => {
    const mod = read("src/client/components/brandMarkPath.ts");
    expect(mod).toContain("GENERATED by scripts/build-brand-assets.mjs");
    expect(mod).toContain("AIRBRIDGE_MARK_PATH");
    expect(mod).toContain("AIRBRIDGE_MARK_VIEWBOX");
    for (const stop of GRADIENT_STOPS) {
      expect(mod, `brandMarkPath.ts missing gradient stop ${stop}`).toContain(stop);
    }

    const icons = read("src/client/components/DeviceIcons.tsx");
    expect(icons).toContain("brandMarkPath.js");
    expect(icons).toContain("fillRule=\"evenodd\"");
    expect(icons).not.toContain("strokeDasharray");
    expect(icons).not.toContain("#34D399");
  });

  it("keeps the one-colour lockup for docs and print", () => {
    const lockup = read("assets/brand/lockup-mono.svg");
    expect(lockup).toContain('fill="#111111"');
    expect(lockup).toContain(">AirBridge</text>");
  });
});
